// #6a993d794918a5e83bc3231b (#c3231b) AC5 — истёкшая сессия → «כניסה מחדש» с плашкой «פג תוקף החיבור» (кейс AUTH-LG-009).
// spec: specs/auth-login.md (5.2) · seed: tests/seed.user.spec.ts.
// Только в окне теста: expires_at сдвинут в прошлое, refresh_token заменён, ответ обновления токена ПОДМЕНЁН (400).
// Настоящий refresh_token из .qa/auth/user.json на сервер не отправляется — общая сессия не тратится.
import { test, expect } from '../../fixtures';
import { readSession } from '../support/session';
import { mockAuth, REFRESH_TOKEN } from '../support/auth-mocks';

test.describe('Истечение сессии (#6a993d794918a5e83bc3231b)', () => {
  test('user: истёкшая сессия на /candidates → /login?notice=expired, «כניסה מחדש», «פג תוקף החיבור», почта подставлена @desktop @prod-safe #6a993d794918a5e83bc3231b', async ({ asUser }) => {
    const email = readSession('user').user.email;
    const page = await asUser('user');
    const refresh = await mockAuth(page, REFRESH_TOKEN, {
      status: 400,
      body: { code: 'refresh_token_not_found', message: 'Invalid Refresh Token: Refresh Token Not Found' },
    });

    // Страница того же адреса без приложения — чтобы поменять сессию до запуска кода сайта.
    await page.goto('/favicon.svg');
    const patched = await page.evaluate(() => {
      const key = Object.keys(localStorage).find((k) => /^sb-.+-auth-token$/.test(k));
      if (!key) return false;
      const s = JSON.parse(localStorage.getItem(key)!);
      s.expires_at = Math.floor(Date.now() / 1000) - 3600;
      s.refresh_token = 'qa-auto-expired-refresh-token';
      localStorage.setItem(key, JSON.stringify(s));
      return true;
    });
    expect(patched, 'в .qa/auth/user.json нет сессии — npm run qa-login').toBe(true);

    await page.goto('/candidates');
    // AC5 «כאשר תוקף הסשן פג … כל גישה חוזרת לנתונים מחייבת התחברות מחדש».
    await page.waitForURL((u) => u.pathname === '/login' && u.searchParams.get('notice') === 'expired');
    expect(refresh.calls.length, 'было обновление токена (подменённое)').toBeGreaterThan(0);
    expect(await page.evaluate(() => history.state?.usr?.from)).toBe('/candidates');

    await expect(page.getByRole('heading', { level: 1, name: 'כניסה מחדש' })).toBeVisible();
    const notice = page.getByTestId('session-expired');
    await expect(notice).toContainText('פג תוקף החיבור');
    await expect(notice).toContainText('מטעמי אבטחה החיבור שלכם הסתיים. היכנסו שוב כדי להמשיך.');
    await expect(page.getByRole('textbox', { name: 'מייל' })).toHaveValue(email);
    await expect(page.getByLabel('סיסמה', { exact: true })).toBeFocused();
    await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);
    await expect(page.getByText('טוען את החשבון…')).toHaveCount(0);
  });
});
